import unittest

import text_tools


class TextToolsTests(unittest.TestCase):
    def test_module_loads(self):
        self.assertIsNotNone(text_tools)

    def test_slugify_lowercases_and_hyphenates_words(self):
        self.assertEqual(text_tools.slugify("Hello, World!"), "hello-world")
        self.assertEqual(text_tools.slugify("Release 2.0"), "release-2-0")

    def test_slugify_collapses_and_trims_separators(self):
        self.assertEqual(
            text_tools.slugify("  --Foo___Bar   Baz--  "),
            "foo-bar-baz",
        )

    def test_slugify_empty_or_non_alphanumeric_returns_empty(self):
        self.assertEqual(text_tools.slugify(""), "")
        self.assertEqual(text_tools.slugify("   ---!!!   "), "")


if __name__ == '__main__':
    unittest.main()

