"""Small text helpers."""

import re

_NON_ALNUM_RE = re.compile(r"[^a-z0-9]+")


def slugify(text: str) -> str:
    """Convert text into a lowercase hyphenated ASCII slug."""
    return _NON_ALNUM_RE.sub("-", text.lower()).strip("-")
